277	// result even without a trailing newline, while a trailing whitespace-only
278	// tail yields no extra result — under every chunking.
279	func TestNormalizeChunkedInputTail(t *testing.T) {
280		cases := []struct {
281			name        string
282			input       string
283			wantResults int
284			wantLast    string // action of the last result, "" when none
285		}{
286			{"final log without trailing newline", validLog("a") + "\n" + validLog("b"), 2, "b"},
287			{"trailing whitespace without newline", validLog("a") + "\n" + "  \t ", 1, "a"},
288			{"trailing blank lines", validLog("a") + "\n\n  \n", 1, "a"},
289			{"only whitespace after final newline", validLog("a") + "\n" + " \r\n\t\n", 1, "a"},
290		}
291		for _, tc := range cases {
292			t.Run(tc.name, func(t *testing.T) {
293				base, failures := assertChunkingInvariant(t, tc.input)
294				if failures != 0 {
295					t.Fatalf("valid logs must report zero failures, got %d", failures)
296				}
297				results := decodeResults(t, []byte(base))
298				if len(results) != tc.wantResults {
299					t.Fatalf("expected %d results, got %#v", tc.wantResults, results)
300				}
301				last := results[len(results)-1]
302				if last["ok"] != true || eventOf(t, last)["action"] != tc.wantLast {
303					t.Fatalf("last result mismatch: %#v", last)
304				}
305			})
306		}
307	}
