58	// A read fault that delivers the complete lines and an unterminated tail in
59	// the SAME Read must preserve exactly the newline-ended processing: the
60	// in-network success on physical line 1 and the timestamp failure on
61	// physical line 4 (not renumbered for the filtered line 2 or blank line 3).
62	// The tail is swallowed with the read whether it is already a complete,
63	// admittable JSON object or itself has an invalid timestamp.
64	func TestNormalizeReaderFilteredReadFaultWithBytesInSameRead(t *testing.T) {
65		filter, complete := filteredInterruptFixture(t)
66		cases := []struct {
67			name     string
68			fragment string
69			marker   string // text unique to the fragment, must never appear in output
70		}{
71			{
72				name:     "tail is a complete admittable JSON object",
73				fragment: `{"timestamp":"2026-01-02T00:00:00Z","action":"tail-in-allowed","source_ip":"192.0.2.77"}`,
74				marker:   "tail-in-allowed",
75			},
76			{
77				name:     "tail carries an invalid timestamp",
78				fragment: `{"timestamp":"not-a-time","action":"tail-bad-time","source_ip":"192.0.2.77"}`,
79				marker:   "tail-bad-time",
80			},
81		}
82		for _, tc := range cases {
83			t.Run(tc.name, func(t *testing.T) {
84				src := &scriptReader{steps: []scriptStep{
85					// Complete lines, the newline-less tail, and the fault all
86					// become available in a single Read.
87					{data: []byte(complete + tc.fragment), err: errSimulatedRead},
88				}}
89				var out bytes.Buffer
90				failures, err := NormalizeReaderFiltered(src, &out, filter)
91				if err == nil {
92					t.Fatalf("a read fault must not be reported as normal completion, even with %d failures", failures)
93				}
94				if !errors.Is(err, ErrLogRead) {
95					t.Fatalf("caller must recognize ErrLogRead, got %v", err)
96				}
97				if !errors.Is(err, errSimulatedRead) {
98					t.Fatalf("the reader's original cause must stay reachable, got %v", err)
99				}
100				if errors.Is(err, ErrLogWrite) {
101					t.Fatalf("a healthy writer must not tag the result as a write failure: %v", err)
102				}
103				if !strings.Contains(err.Error(), errSimulatedRead.Error()) {
104					t.Fatalf("error text must retain the original read cause, got %q", err.Error())
105				}
106				if failures != 1 {
107					t.Fatalf("only the complete invalid line 4 counts; the failed-read tail adds nothing, got %d", failures)
108				}
109	
110				results := decodeResults(t, out.Bytes())
111				if len(results) != 2 {
112					t.Fatalf("expected line 1 success and line 4 failure only, got %#v", results)
113				}
114				if results[0]["line"] != float64(1) || results[0]["ok"] != true {
115					t.Fatalf("in-network line 1 must be emitted with its physical number: %#v", results[0])
116				}
117				event := eventOf(t, results[0])
118				if event["action"] != "in-allowed" || event["source_ip"] != "192.0.2.10" {
119					t.Fatalf("line 1 event mismatch: %#v", event)
120				}
121				if results[1]["line"] != float64(4) || results[1]["ok"] != false {
122					t.Fatalf("outside-source invalid-time line must keep physical number 4: %#v", results[1])
123				}
124				if _, exists := results[1]["event"]; exists {
125					t.Fatalf("failed record must not carry an event: %#v", results[1])
126				}
127				if msg, _ := results[1]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
128					t.Fatalf("failed record must keep the timestamp-specific reason, got %q", msg)
129				}
130	
131				if bytes.Contains(out.Bytes(), []byte("out-dropped")) {
132					t.Fatalf("the out-of-network valid line must produce no record: %q", out.String())
133				}
134				if bytes.Contains(out.Bytes(), []byte(tc.marker)) {
135					t.Fatalf("the newline-less tail belongs to the failed read and must leave no record: %q", out.String())
136				}
137	
138				// The fault run must equal a healthy read of exactly the complete
139				// lines under the same filter: filtering, blank-line skipping,
140				// ordering, and numbering are all byte-for-byte unchanged.
141				var healthy bytes.Buffer
142				healthyFailures, healthyErr := NormalizeReaderFiltered(strings.NewReader(complete), &healthy, filter)
143				if healthyErr != nil || healthyFailures != 1 {
144					t.Fatalf("test setup: healthy reference read failed: failures=%d err=%v", healthyFailures, healthyErr)
145				}
146				if !bytes.Equal(out.Bytes(), healthy.Bytes()) {
147					t.Fatalf("fault run output must equal a healthy read of the complete lines:\nfault:   %q\nhealthy: %q", out.String(), healthy.String())
148				}
149			})
150		}
151	}
152	
153	// When the only complete line before the interruption is a valid but
154	// out-of-network log, the run has no output and zero failures -- the same
155	// observable shape as "nothing matched" -- yet the read error must still be
156	// visible so callers do not mistake a cut-off stream for an empty result.
157	func TestNormalizeReaderFilteredReadFaultAfterOnlyDroppedLines(t *testing.T) {
158		filter, _ := filteredInterruptFixture(t)
159		outsideOnly := `{"timestamp":"2026-01-02T00:00:00Z","action":"out-dropped","source_ip":"198.51.100.20"}` + "\n"
160		tail := `{"timestamp":"2026-01-02T00:00:00Z","action":"tail-in-allowed","source_ip":"192.0.2.77"}`
161	
162		cases := []struct {
163			name string
164			step scriptStep
165		}{
166			{
167				name: "fault stands alone after the newline",
168				step: scriptStep{data: []byte(outsideOnly), err: errSimulatedRead},
169			},
170			{
171				name: "fault delivers an admittable newline-less fragment too",
172				step: scriptStep{data: []byte(outsideOnly + tail), err: errSimulatedRead},
173			},
174		}
175		for _, tc := range cases {
176			t.Run(tc.name, func(t *testing.T) {
177				src := &scriptReader{steps: []scriptStep{tc.step}}
178				var out bytes.Buffer
179				failures, err := NormalizeReaderFiltered(src, &out, filter)
180				if !errors.Is(err, ErrLogRead) || !errors.Is(err, errSimulatedRead) {
181					t.Fatalf("want ErrLogRead wrapping the read cause, got %v", err)
182				}
183				if failures != 0 {
184					t.Fatalf("no complete line failed normalization, got %d failures", failures)
185				}
186				if out.Len() != 0 {
187					t.Fatalf("dropped lines and a failed-read fragment must leave empty output, got %q", out.String())
188				}
189			})
190		}
191	
192		// Control: the same out-of-network-only bytes ending in a clean EOF are
193		// genuinely "no events hit" -- empty output, zero failures, and NO error.
194		// That nil-vs-ErrLogRead distinction is what lets callers tell the two
195		// empty-result cases apart.
196		var clean bytes.Buffer
197		failures, err := NormalizeReaderFiltered(strings.NewReader(outsideOnly), &clean, filter)
198		if err != nil {
199			t.Fatalf("clean EOF with no admitted events must not be an error, got %v", err)
200		}
201		if failures != 0 || clean.Len() != 0 {
202			t.Fatalf("clean EOF with only dropped lines must be an empty, failure-free result, got failures=%d out=%q", failures, clean.String())
203		}
204	}
