206	// The same batch terminated by a clean EOF treats the newline-less tail as
207	// the fifth physical line per the existing rules: an admittable tail appends
208	// a line-5 success, an invalid-time tail appends a line-5 failure (raising
209	// the count to 2), the pre-existing line-4 failure is never lost, and no
210	// stream-level error is returned.
211	func TestNormalizeReaderFilteredCleanEOFProcessesNewlineLessTail(t *testing.T) {
212		filter, complete := filteredInterruptFixture(t)
213		cases := []struct {
214			name         string
215			fragment     string
216			tailOK       bool
217			wantFailures int
218		}{
219			{
220				name:         "tail is a complete admittable JSON object",
221				fragment:     `{"timestamp":"2026-01-02T00:00:00Z","action":"tail-in-allowed","source_ip":"192.0.2.77"}`,
222				tailOK:       true,
223				wantFailures: 1,
224			},
225			{
226				name:         "tail carries an invalid timestamp",
227				fragment:     `{"timestamp":"not-a-time","action":"tail-bad-time","source_ip":"192.0.2.77"}`,
228				tailOK:       false,
229				wantFailures: 2,
230			},
231		}
232		for _, tc := range cases {
233			t.Run(tc.name, func(t *testing.T) {
234				src := &scriptReader{steps: []scriptStep{
235					// All bytes and clean EOF become available together.
236					{data: []byte(complete + tc.fragment), err: io.EOF},
237				}}
238				var out bytes.Buffer
239				failures, err := NormalizeReaderFiltered(src, &out, filter)
240				if err != nil {
241					t.Fatalf("clean EOF is ordinary completion, including a final line without newline, got %v", err)
242				}
243				if failures != tc.wantFailures {
244					t.Fatalf("want %d failures (line 4 plus any tail failure), got %d", tc.wantFailures, failures)
245				}
246				results := decodeResults(t, out.Bytes())
247				if len(results) != 3 {
248					t.Fatalf("expected line 1 success, line 4 failure, line 5 tail result, got %#v", results)
249				}
250				if results[0]["line"] != float64(1) || results[0]["ok"] != true {
251					t.Fatalf("line 1 must keep its physical number and success: %#v", results[0])
252				}
253				if eventOf(t, results[0])["action"] != "in-allowed" {
254					t.Fatalf("line 1 event mismatch: %#v", results[0])
255				}
256				// The earlier complete-line failure must not be ignored just
257				// because the stream ended on an additional line.
258				if results[1]["line"] != float64(4) || results[1]["ok"] != false {
259					t.Fatalf("line 4 failure must survive ahead of the tail: %#v", results[1])
260				}
261				if _, exists := results[1]["event"]; exists {
262					t.Fatalf("line 4 failure must not carry an event: %#v", results[1])
263				}
264				if msg, _ := results[1]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
265					t.Fatalf("line 4 must keep the timestamp-specific reason, got %q", msg)
266				}
267				if results[2]["line"] != float64(5) || results[2]["ok"] != tc.tailOK {
268					t.Fatalf("tail must be processed as physical line 5 (ok=%v): %#v", tc.tailOK, results[2])
269				}
270				if tc.tailOK {
271					if eventOf(t, results[2])["action"] != "tail-in-allowed" {
272						t.Fatalf("line 5 event mismatch: %#v", results[2])
273					}
274				} else {
275					if _, exists := results[2]["event"]; exists {
276						t.Fatalf("line 5 failure must not carry an event: %#v", results[2])
277					}
278					if msg, _ := results[2]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
279						t.Fatalf("line 5 must keep the timestamp-specific reason, got %q", msg)
280					}
281				}
282			})
283		}
284	}
