538	func TestNormalizeUTCYearRange(t *testing.T) {
539		// Legal four-digit-year inputs whose UTC conversion escapes 0000-9999
540		// must fail; RFC3339Nano cannot represent the result and detection
541		// rules must never receive an out-of-range canonical timestamp.
542		outOfRange := []string{
543			"0000-01-01T00:00:00+00:01",
544			"0000-01-01T00:00:59+01:00",
545			"0000-01-01T00:00:00+23:59", // largest legal offset: lands in year -1
546			"9999-12-31T23:59:59-00:01",
547			"9999-12-31T23:00:00-01:00",
548			"9999-12-31T23:59:00-23:59",
549		}
550		for _, in := range outOfRange {
551			for _, wrapper := range []string{
552				`{"timestamp":"` + in + `","action":"a"}`,
553				`{"time":"` + in + `","action":"a"}`,
554			} {
555				results := runNormalize(t, wrapper)
556				if results[0]["ok"] != false {
557					t.Fatalf("timestamp %q must fail after UTC conversion, got %#v", in, results[0])
558				}
559				if _, exists := results[0]["event"]; exists {
560					t.Fatalf("out-of-range timestamp %q must not emit an event", in)
561				}
562				msg, _ := results[0]["error"].(string)
563				if !strings.Contains(msg, FieldTimestamp) {
564					t.Fatalf("error for %q must name %q, got %q", in, FieldTimestamp, msg)
565				}
566				if !strings.Contains(msg, "UTC year") || !strings.Contains(msg, "0000-9999") {
567					t.Fatalf("error for %q must state the UTC year range, got %q", in, msg)
568				}
569			}
570		}
571	
572		// The range endpoints are inclusive and fractional precision must
573		// survive at the edges, with trailing zeros still trimmed.
574		ok := map[string]string{
575			"0000-01-01T00:00:00Z":             "0000-01-01T00:00:00Z",
576			"0000-01-01T00:01:00+00:01":        "0000-01-01T00:00:00Z",
577			"0000-01-01T00:00:00-23:59":        "0000-01-01T23:59:00Z",
