886			}
887			msg, _ := results[0]["error"].(string)
888			if !strings.Contains(msg, tc.field) {
889				t.Fatalf("error for %s must name field %q, got %q", tc.input, tc.field, msg)
890			}
891		}
892	}
893	
894	func TestNormalizeInvalidJSONNumbersFail(t *testing.T) {
895		// Tokens that are not legal JSON numbers must fail the whole line with
896		// an error and no partial event, even inside unmapped fields.
897		cases := []string{
898			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":NaN}`,
899			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":Infinity}`,
900			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":-Infinity}`,
901			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":01}`,
902			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":+1}`,
903			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":1.}`,
904			`{"timestamp":"2026-01-02T00:00:00Z","action":"a","x":{"nested":007}}`,
