201			got := results[i]
202			if got["line"] != w.line || got["ok"] != w.ok {
203				t.Fatalf("record %d mismatch: want line=%v ok=%v, got %#v", i, w.line, w.ok, got)
204			}
205			if _, marked := got["filtered"]; marked {
206				t.Fatalf("record %d must carry no filter marker: %#v", i, got)
207			}
208			if !w.ok {
209				if _, exists := got["event"]; exists {
210					t.Fatalf("the out-of-range invalid line must carry no event: %#v", got)
211				}
212				if msg, _ := got["error"].(string); !strings.Contains(msg, FieldTimestamp) {
213					t.Fatalf("the failure must keep its original timestamp reason, got %q", msg)
214				}
215				continue
216			}
217			event := eventOf(t, got)
218			if event["action"] != w.action || event["source_ip"] != w.sourceIP {
219				t.Fatalf("record %d event mismatch: %#v", i, event)
220			}
221		}
222	
223		// Field normalization and extra preservation are exactly the unfiltered
224		// behavior: the alias-sourced line keeps its extra string, the trailing
225		// hit keeps its nested object.
226		if got := eventOf(t, results[1])["extra"].(map[string]any)["trace"]; got != "t-9" {
227			t.Fatalf("extra fields of an admitted alias line must survive filtering, got %#v", got)
228		}
229		if got := eventOf(t, results[4])["extra"].(map[string]any)["keep"].(map[string]any)["n"]; got != float64(2) {
230			t.Fatalf("nested extra content of an admitted line must survive filtering, got %#v", got)
231		}
232	}
233	
234	// TestSourceCIDRFilterSlash31KeepsBothAddresses pins the two-address network:
235	// 192.0.2.3/31 admits both 192.0.2.2 and 192.0.2.3 — neither address is
236	// excluded as a network or broadcast address — while the immediate neighbors
237	// 192.0.2.1 and 192.0.2.4 are dropped. The same network spelled with its
238	// other host address selects identically.
239	func TestSourceCIDRFilterSlash31KeepsBothAddresses(t *testing.T) {
240		input := strings.Join([]string{
241			`{"timestamp":` + validTS + `,"action":"below","source_ip":"192.0.2.1"}`,             // line 1 dropped
242			`{"timestamp":` + validTS + `,"action":"low-of-pair","source_ip":"192.0.2.2"}`,       // line 2 admitted
243			`{"timestamp":` + validTS + `,"action":"high-of-pair","src_ip":"192.0.2.3"}`,         // line 3 admitted via alias
244			`{"timestamp":` + validTS + `,"action":"mapped-low","source_ip":"::ffff:192.0.2.2"}`, // line 4 admitted
245			`{"timestamp":` + validTS + `,"action":"above","source_ip":"192.0.2.4"}`,             // line 5 dropped
246		}, "\n") + "\n"
247	
248		var outputs []string
249		for _, spelled := range []string{"192.0.2.3/31", "192.0.2.2/31"} {
250			filter, err := ParseSourceCIDRFilter(spelled)
251			if err != nil {
252				t.Fatal(err)
253			}
254			results, failures := runNormalizeFiltered(t, input, &filter)
255			if failures != 0 {
256				t.Fatalf("filter %q: an all-valid batch must have zero failures, got %d", spelled, failures)
257			}
258			if len(results) != 3 {
259				t.Fatalf("filter %q: both /31 addresses and the mapped spelling must survive, got %#v", spelled, results)
260			}
261			wantLines := []float64{2, 3, 4}
262			wantActions := []string{"low-of-pair", "high-of-pair", "mapped-low"}
263			wantSources := []string{"192.0.2.2", "192.0.2.3", "192.0.2.2"}
264			for i := range wantLines {
265				if results[i]["line"] != wantLines[i] || results[i]["ok"] != true {
266					t.Fatalf("filter %q: record %d must keep physical line %v: %#v", spelled, i, wantLines[i], results[i])
267				}
268				event := eventOf(t, results[i])
269				if event["action"] != wantActions[i] || event["source_ip"] != wantSources[i] {
270					t.Fatalf("filter %q: record %d event mismatch: %#v", spelled, i, event)
271				}
272			}
273			var rendered strings.Builder
274			for _, r := range results {
275				rendered.WriteString(eventOf(t, r)["action"].(string))
276				rendered.WriteByte(';')
277			}
278			outputs = append(outputs, rendered.String())
279		}
280		if outputs[0] != outputs[1] {
281			t.Fatalf("the two host spellings of one /31 must select identically: %q vs %q", outputs[0], outputs[1])
282		}
283	}
284	
285	// TestSourceCIDRFilterBoundaryAllMissesCleanEmpty pins that a batch of valid
286	// logs whose sources all fall immediately outside a boundary network — or are
287	// absent — ends normally: no records, zero failures.
288	func TestSourceCIDRFilterBoundaryAllMissesCleanEmpty(t *testing.T) {
289		filter, err := ParseSourceCIDRFilter("192.0.129.7/17")
290		if err != nil {
291			t.Fatal(err)
292		}
293		input := strings.Join([]string{
294			`{"timestamp":` + validTS + `,"action":"just-below","source_ip":"192.0.127.255"}`,
295			`{"timestamp":` + validTS + `,"action":"just-above","source_ip":"192.1.0.0"}`,
296			`{"timestamp":` + validTS + `,"action":"v6-same-tail","source_ip":"::192.0.128.0"}`,
297			`{"timestamp":` + validTS + `,"action":"no-source"}`,
298		}, "\n") + "\n"
